7: class NewsListPage extends StatefulWidget {
8:   const NewsListPage({super.key});
9: 
10:   @override
11:   State<NewsListPage> createState() => _NewsListPageState();
12: }
13: 
14: class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
15:   static final _tween = Tween<double>(begin: 0.25, end: 1);
16: 
17:   late final NewsListState _state;
18: 
19:   late final AnimationController _scaleController;
20:   late final Animation<double> _scaleAnimation;
21: 
22:   @override
23:   void initState() {
24:     super.initState();
25:     _initAnimation();
26:     _initData();
27:   }
28: 
29:   @override
30:   void dispose() {
31:     _state.dispose();
32:     _scaleController.dispose();
33:     super.dispose();
34:   }
35: 
36:   void _initAnimation() {
37:     _scaleController = AnimationController(
38:       vsync: this,
39:       duration: Duration(milliseconds: 200),
40:     );
41:     _scaleAnimation = _tween.animate(_scaleController);
42:   }
43: 
44:   void _initData() {
45:     final newsRepository = context.read<NewsRepository>();
46: 
47:     _state = NewsListState(
48:       loadCachedNews: () => newsRepository.loadNewsFeed(NewsFeedFilter.all),
49:       loadFreshNews: () => newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
50:     )..addListener(_onNewsUpdated);
51: 
52:     _state.load();
53:   }
54: 
55:   void _onNewsUpdated() {
56:     if (_scaleController.isDismissed) {
57:       _scaleController.forward(); // запускаем анимацию
