9: 
10: import '../mocks/repository.mocks.dart';
11: 
12: import 'widget.dart';
13: 
14: Future<void> main() async {
15:   await initializeDateFormatting(AppConstants.ruLocale, null);
16: 
17:   group('NewsListPage', () {
18:     final MockNewsRepository mockNewsRepository = MockNewsRepository();
19: 
20:     final newsItems = [
21:       NewsModel(title: 'Заголовок 1', link: 'https://example.com/1', date: DateTime.now()),
22:       NewsModel(title: 'Заголовок 2', link: 'https://example.com/2', date: DateTime.now()),
23:     ];
24: 
25:     final cachedNewsItems = [
26:       NewsModel(title: 'Из кэша', link: 'https://example.com/cached', date: DateTime.now()),
27:     ];
28: 
29:     late Completer<List<NewsModel>> freshNewsCompleter;
30: 
31:     setUp(() {
32:       reset(mockNewsRepository);
33:       freshNewsCompleter = Completer<List<NewsModel>>();
34: 
35:       when(mockNewsRepository.loadNewsFeed(NewsFeedFilter.all)).thenAnswer((_) async => cachedNewsItems);
36:       when(mockNewsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)))
37:           .thenAnswer((_) => freshNewsCompleter.future);
38:       when(mockNewsRepository.saveNewsList(any)).thenAnswer((_) async {});
39:     });
40: 
41:     testWidgets('should display cached news first and then fresh news', (WidgetTester tester) async {
42:       final List<String> renderedTitles = [];
43: 
44:       await tester.pumpWidget(
45:         buildWidget(
46:           providers: [
47:             Provider<NewsRepository>.value(value: mockNewsRepository),
48:           ],
49:           child: const _NewsListPageObserver(),
50:         ),
51:       );
52:       _titlesOf(tester, renderedTitles);
53: 
54:       // Кэш: пока сеть не ответила, на экране уже есть лента из БД.
55:       await tester.pump();
56:       expect(find.text('Из кэша'), findsOneWidget);
57:       expect(find.text('Заголовок 1'), findsNothing);
58:       _titlesOf(tester, renderedTitles);
59: 
60:       // Сеть: список заменяется свежими новостями, кэш больше не показывается.
61:       freshNewsCompleter.complete(newsItems);
62:       await tester.pumpAndSettle();
63:       debugPrint('DEBUG settled: ${tester.allWidgets.whereType<Text>().map((Text t) => t.data).toList()}');
64: 
65:       expect(find.text('Заголовок 1'), findsOneWidget);
66:       expect(find.text('Заголовок 2'), findsOneWidget);
67:       expect(find.text('Из кэша'), findsNothing);
68:       expect(find.text('Заголовок 3'), findsNothing);
69:       _titlesOf(tester, renderedTitles);
70: 
71:       // Порядок отрисовки: сначала кэш, затем сеть.
72:       expect(renderedTitles, ['Из кэша', 'Заголовок 1']);
73:     });
74: 
75:     testWidgets('should keep cached news when network request fails', (WidgetTester tester) async {
76:       await tester.pumpWidget(
77:         buildWidget(
78:           providers: [
79:             Provider<NewsRepository>.value(value: mockNewsRepository),
80:           ],
81:           child: const NewsListPage(),
82:         ),
83:       );
84: 
85:       await tester.pump();
86:       expect(find.text('Из кэша'), findsOneWidget);
87: 
88:       freshNewsCompleter.completeError(Exception('network error'));
89:       await tester.pump();
90:       await tester.pump(const Duration(milliseconds: 300));
91: 
92:       expect(find.text('Из кэша'), findsOneWidget);
93:       expect(tester.takeException(), isNull);
94:     });
95:   });
96: }
97: 
98: /// Собирает заголовки, реально отрисованные лентой, в порядке появления.
99: void _titlesOf(WidgetTester tester, List<String> collected) {
100:   final String? title = tester
101:       .widgetList<NewsCard>(find.byType(NewsCard))
102:       .map((NewsCard card) => card.model.title)
103:       .firstOrNull;
104: 
105:   if (title != null && collected.lastOrNull != title) collected.add(title);
106: }
107: 
108: class _NewsListPageObserver extends StatelessWidget {
109:   const _NewsListPageObserver();
110: 
111:   @override
112:   Widget build(BuildContext context) => const NewsListPage();
113: }

