1: import 'dart:async';
2: 
3: import 'package:flutter/foundation.dart';
4: import 'package:mad_flutter_practicum/domain/model/news_model.dart';
5: 
6: /// Состояние ленты новостей в паттерне cache-then-network: сначала отдаёт кэш,
7: /// затем обновляется свежими данными из сети.
8: class NewsListState extends ChangeNotifier {
9:   NewsListState({required this.loadCachedNews, required this.loadFreshNews});
10: 
11:   final Future<List<NewsModel>> Function() loadCachedNews;
12:   final Future<List<NewsModel>> Function() loadFreshNews;
13: 
14:   final ValueNotifier<List<NewsModel>> news = ValueNotifier<List<NewsModel>>(const []);
15: 
16:   /// Показывает кэш, параллельно запрашивает сеть и применяет ответ, когда он придёт.
17:   Future<void> load() async {
18:     // Запрос в сеть стартует сразу и подписывается на ошибку, не дожидаясь кэша.
19:     final Future<List<NewsModel>> freshNews = loadFreshNews().catchError(
20:       (Object _) => const <NewsModel>[],
21:     );
22: 
23:     final List<NewsModel> cached = await loadCachedNews();
24:     _apply(cached);
25: 
26:     // Сеть недоступна: остаёмся на кэше, ошибку показывать нечем.
27:     _apply(await freshNews);
28:   }
29: 
30:   void _apply(List<NewsModel> value) {
31:     if (value.isEmpty) return;
32: 
33:     news.value = value;
34:     notifyListeners();
35:   }
36: 
37:   @override
38:   void dispose() {
39:     news.dispose();
40:     super.dispose();
41:   }
42: }

1: import 'package:mad_flutter_practicum/app/app.dart';
2: import 'package:mad_flutter_practicum/domain/domain.dart';
3: 
4: import 'news_list_state.dart';
5: import 'widgets/widgets.dart';
6: 
7: class NewsListPage extends StatefulWidget {
8:   const NewsListPage({super.key});
9: 
10:   @override
11:   State<NewsListPage> createState() => _NewsListPageState();
12: }
13: 
14: class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
15:   static final _tween = Tween<double>(begin: 0.25, end: 1);
16: 
17:   late final NewsListState _state;
18: 
19:   late final AnimationController _scaleController;
20:   late final Animation<double> _scaleAnimation;
21: 
22:   @override
23:   void initState() {
24:     super.initState();
25:     _initAnimation();
26:     _initData();
27:   }
28: 
29:   @override
30:   void dispose() {
31:     _state.dispose();
32:     _scaleController.dispose();
33:     super.dispose();
34:   }
35: 
36:   void _initAnimation() {
37:     _scaleController = AnimationController(
38:       vsync: this,
39:       duration: Duration(milliseconds: 200),
40:     );
41:     _scaleAnimation = _tween.animate(_scaleController);
42:   }
43: 
44:   void _initData() {
45:     final newsRepository = context.read<NewsRepository>();
46: 
47:     _state = NewsListState(
48:       loadCachedNews: () => newsRepository.loadNewsFeed(NewsFeedFilter.all),
49:       loadFreshNews: () => newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
50:     )..addListener(_onNewsUpdated);
51: 
52:     _state.load();
53:   }
54: 
55:   void _onNewsUpdated() {
56:     if (_scaleController.isDismissed) {
57:       _scaleController.forward(); // запускаем анимацию
58:     }
59:   }
60: 
61:   @override
62:   Widget build(BuildContext context) {
63:     return Scaffold(
64:       appBar: AppBar(title: Text(context.loc.news)),
65:       body: ValueListenableBuilder<List<NewsModel>>(
66:         valueListenable: _state.news,
67:         builder: (BuildContext context, List<NewsModel> data, _) {
68:           if (data.isEmpty) return const SizedBox.shrink();
69: 
70:           return ScaleTransition(
71:             scale: _scaleAnimation,
72:             child: ListView.builder(
73:               itemCount: data.length,
74:               itemBuilder: (BuildContext context, int index) {
75:                 final NewsModel news = data[index];
76: 
77:                 return Padding(
78:                   key: ValueKey(news.link),
79:                   padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
80:                   child: NewsCard(model: news),
81:                 );
82:               },
83:               padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
84:             ),
85:           );
86:         },
87:       ),
88:     );
89:   }
90: }

